<div class="modal fade review-modal" id="reviewModal" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-dialog-centered"><form method="post" action="/ulasan" class="modal-content">@csrf<div class="modal-header"><div><h2 class="h5 mb-1"><i class="fas fa-star me-2 text-warning"></i>Beri Ulasan Layanan</h2><small>Masukan Anda membantu kami meningkatkan pelayanan.</small></div><button type="button" class="btn-close btn-close-white" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="mb-4"><label class="form-label fw-bold">Nama Anda</label><input name="name" class="form-control form-control-lg" maxlength="100" required placeholder="Tulis nama Anda"></div><label class="form-label fw-bold d-block text-center">Bagaimana penilaian Anda?</label><div class="review-stars mb-4"><input id="star5" type="radio" name="rating" value="5" required><label for="star5">★</label><input id="star4" type="radio" name="rating" value="4"><label for="star4">★</label><input id="star3" type="radio" name="rating" value="3"><label for="star3">★</label><input id="star2" type="radio" name="rating" value="2"><label for="star2">★</label><input id="star1" type="radio" name="rating" value="1"><label for="star1">★</label></div><div class="mb-4"><label class="form-label fw-bold">Komentar dan Saran <span class="fw-normal text-secondary">(opsional)</span></label><textarea name="feedback" class="form-control" rows="4" maxlength="1000" placeholder="Tuliskan pengalaman, komentar, atau saran Anda untuk layanan kami."></textarea></div><button class="btn review-submit w-100 py-3"><i class="fas fa-paper-plane me-2"></i>Kirim Ulasan</button></div></form></div></div>
